import java.util.*;
import java.util.stream.IntStream;

public class E {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        sc.close();
        int l = s.length();
        if (l < 2) {
            System.out.println(s.equals("0") || s.equals("_") || s.equals("X") ? 1 : 0);
            System.exit(0);
        } else if (l == 2) {
            long count = IntStream.iterate(10, i -> i <= 95, i -> i + 5)
                .filter(i -> i % 25 == 0)
                .mapToObj(Integer::toString)
                .filter(str -> {
                    char c0 = s.charAt(0), c1 = s.charAt(1);
                    if (c0 >= '0' && c0 <= '9' && c1 >= '0' && c1 <= '9')
                        return s.equals(str);
                    if (c0 >= '0' && c0 <= '9')
                        return c0 == str.charAt(0);
                    if (c0 == '_') {
                        if (c1 >= '0' && c1 <= '9')
                            return c1 == str.charAt(1);
                        return true;
                    }
                    if (c1 >= '0' && c1 <= '9')
                        return c1 == str.charAt(1);
                    return c1 == '_';
                })
                .count();
            System.out.println(count);
            System.exit(0);
        } else {
            int start = (int) Math.pow(10, l - 1);
            int end = (int) Math.pow(10, l);
            long count = IntStream.iterate(start, i -> i < end, i -> i + 25)
                .filter(i -> {
                    String str = Integer.toString(i);
                    Set<Character> set = new HashSet<>();
                    for (int j = 0; j < l; j++) {
                        char ch = s.charAt(j);
                        if (ch == '_') continue;
                        if (ch == 'X') set.add(str.charAt(j));
                        else if (ch != str.charAt(j)) return false;
                    }
                    return set.size() < 2;
                })
                .count();
            System.out.println(count);
        }
    }
}
